'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['dispatchMessage']);
const { dispatchMessage } = api;

(async () => {
  assert.strictEqual(await dispatchMessage([], 'x'), undefined);

  const order = [];
  const handlers = [
    async (message) => {
      order.push('first-start:' + message);
      await Promise.resolve();
      order.push('first-end');
      return undefined;
    },
    (message) => {
      order.push('second:' + message);
      return 0;
    },
    () => {
      order.push('third');
      return 'wrong';
    }
  ];
  const snapshot = handlers.slice();
  assert.strictEqual(await dispatchMessage(handlers, 'hello'), 0);
  assert.deepStrictEqual(order, ['first-start:hello', 'first-end', 'second:hello']);
  assert.deepStrictEqual(handlers, snapshot);

  let laterCalled = false;
  assert.strictEqual(await dispatchMessage([
    () => Promise.resolve(undefined),
    () => false,
    () => { laterCalled = true; }
  ], {}), false);
  assert.strictEqual(laterCalled, false);

  assert.strictEqual(await dispatchMessage([() => undefined, async () => undefined], null), undefined);
  assert.strictEqual(await dispatchMessage([() => null, () => 'later'], 1), null);

  let invoked = 0;
  await assert.rejects(dispatchMessage([() => { invoked++; }, 'bad', () => { invoked++; }], 'x'), TypeError);
  assert.strictEqual(invoked, 0);
  await assert.rejects(dispatchMessage(null, 'x'), TypeError);

  const thrown = new Error('thrown');
  let afterThrow = false;
  await assert.rejects(dispatchMessage([
    () => { throw thrown; },
    () => { afterThrow = true; }
  ], 'x'), (error) => error === thrown);
  assert.strictEqual(afterThrow, false);

  const rejected = new Error('rejected');
  let afterReject = false;
  await assert.rejects(dispatchMessage([
    () => Promise.reject(rejected),
    () => { afterReject = true; }
  ], 'x'), (error) => error === rejected);
  assert.strictEqual(afterReject, false);
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

